const isSystemError = !!$json.execution;
const src = isSystemError ? {
  workflow_name: $json.workflow && $json.workflow.name,
  node_name: $json.node && $json.node.name,
  severity: 'medium',
  message: $json.execution && $json.execution.error && $json.execution.error.message,
  error_type: 'N8N_SYSTEM_ERROR',
  trace_id: 'trace_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10),
  run_url: $json.execution && $json.execution.url,
  client_id: 'unknown_client'
} : $json;

const allowedSeverity = ['high', 'medium', 'low'];
const severity = allowedSeverity.includes((src.severity || '').toLowerCase()) ? src.severity.toLowerCase() : 'medium';

return [{
  json: {
    workflow_name: src.workflow_name || 'UNKNOWN_WORKFLOW',
    node_name: src.node_name || 'UNKNOWN_NODE',
    severity,
    message: src.message || 'Unknown error',
    error_type: src.error_type || 'APP_ERROR',
    trace_id: src.trace_id || ('trace_' + Date.now()),
    run_url: src.run_url || '',
    client_id: src.client_id || 'unknown_client',
    schema_version: 1,
    timestamp: new Date().toISOString(),
    raw: src
  }
}];

const SECRET_KEYS = ['access_token', 'refresh_token', 'client_secret', 'authorization', 'password'];

function redact(obj) {
  if (obj === null || typeof obj !== 'object') return obj;
  const clone = Array.isArray(obj) ? [] : {};
  for (const [k, v] of Object.entries(obj)) {
    if (SECRET_KEYS.includes(k.toLowerCase())) {
      clone[k] = '[REDACTED]';
    } else if (typeof v === 'object' && v !== null) {
      clone[k] = redact(v);
    } else {
      clone[k] = v;
    }
  }
  return clone;
}

const raw_sanitized = JSON.stringify(redact($json.raw || {}));
const out = { ...$json };
delete out.raw;
out.raw_sanitized = raw_sanitized;

return [{ json: out }];

const ESCALATION_WINDOW_MIN = 10;
const ESCALATION_THRESHOLD = 3;
const COOLDOWN_MIN = 10;

const err = $('Build Dedupe Key').item.json;
const existing = $json; // may be empty object if no dedupe row found
const now = new Date();

const hit_count = (existing.hit_count ? parseInt(existing.hit_count, 10) : 0) + 1;
const first_seen_at = existing.first_seen_at || err.timestamp;
const last_sent_at = existing.last_sent_at ? new Date(existing.last_sent_at) : null;

const withinCooldown = last_sent_at && (now - last_sent_at) < COOLDOWN_MIN * 60 * 1000;
const recentWindowStart = new Date(now.getTime() - ESCALATION_WINDOW_MIN * 60 * 1000);
const escalated = err.severity !== 'high' && hit_count >= ESCALATION_THRESHOLD && new Date(first_seen_at) > recentWindowStart;
const effectiveSeverity = escalated ? 'high' : err.severity;

const shouldNotify = !withinCooldown && (effectiveSeverity === 'high' || effectiveSeverity === 'medium');

return [{
  json: {
    ...err,
    hit_count,
    first_seen_at,
    last_seen_at: now.toISOString(),
    last_sent_at: shouldNotify ? now.toISOString() : (existing.last_sent_at || ''),
    escalated,
    effective_severity: effectiveSeverity,
    shouldNotify,
    dedupe_row_exists: !!existing.dedupe_key
  }
}];

